    {
      "id": "Edcfc0a0002157fcd",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A mistura entre água de formação rica em bário, cálcio e estrôncio e água do mar rica em sulfato é associada à formação de incrustações de sulfatos, enquanto a composição salina da água produzida também é associada a corrosão e depósitos inorgânicos.",
          "trechos": [
            "Edcfc0a0002157fcd:0:698"
          ],
          "condicoes": [
            "quando há contato entre água de formação e água do mar injetada",
            "no contexto de sistemas de produção e injeção"
          ],
          "limites": [
            "o trecho não fornece critérios quantitativos de compatibilidade nem taxas de incrustação",
            "não há ligação direta com cavitação, vazão, pressão ou redundância de bombas"
          ]
        },
        {
          "proposicao": "Em alguns casos, o sistema de tratamento contém unidades de remoção de sulfato para evitar incrustações, e a injeção de água dessulfatada é apresentada como tendo menor propensão à acidificação do reservatório associada ao desenvolvimento de bactérias redutoras de sulfato.",
          "trechos": [
            "Edcfc0a0002157fcd:0:698",
            "Edcfc0a0002157fcd:698:1389"
          ],
          "condicoes": [
            "em alguns casos de tratamento de água",
            "no contexto de água do mar destinada à injeção"
          ],
          "limites": [
            "o texto não transforma o uso de unidades de remoção de sulfato em requisito universal",
            "não há especificação de eficiência de remoção, condições operacionais ou integração com o sistema de bombeamento"
          ]
        },
        {
          "proposicao": "Nanofiltração e osmose inversa são indicadas para tratar água do mar e água produzida, sobretudo para remoção de íons bivalentes, mas a formação de incrustações nas membranas é apresentada como limitação relevante por reduzir fluxo e afetar desempenho e vida útil.",
          "trechos": [
            "Edcfc0a0002157fcd:698:1389",
            "Edcfc0a0002157fcd:1389:2088"
          ],
          "condicoes": [
            "quando se busca remover sulfatos e carbonatos em sistemas de tratamento com membranas"
          ],
          "limites": [
            "a indicação é técnica e não traz comparação econômica ou critérios de seleção para FPSO",
            "o trecho trata de fluxo em membranas, não de desempenho de bombas de captação ou injeção"
          ]
        }
      ]
    },
